<?php declare(strict_types=1);use FastWebsite\Core\View;$v=static fn(string$f):string=>(string)($values[$f]??'');$editing=is_int($itemId);?><section class="admin-page-heading"><div><h1><?=$editing?'Edit impact story':'Create impact story'?></h1></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/engagement#impact">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><ul><?php foreach($errors as$e):?><li><?=View::escape($e)?></li><?php endforeach;?></ul></div><?php endif;?><form class="content-form" enctype="multipart/form-data" method="post" action="<?=View::escape($baseUrl)?>admin/engagement/impact<?=$editing?'/'.$itemId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><input type="hidden" name="MAX_FILE_SIZE" value="20971520"><section class="form-section"><div class="form-grid"><div class="form-field span-2"><label for="title">Story title *</label><input id="title" name="title" required maxlength="280" value="<?=View::escape($v('title'))?>"></div><div class="form-field span-2"><label for="slug">Public URL</label><input id="slug" name="slug" maxlength="300" value="<?=View::escape($v('slug'))?>"></div><div class="form-field"><label for="department_id">Department</label><select id="department_id" name="department_id"><option value="">Faculty-wide</option><?php foreach($departments as$d):?><option value="<?=(int)$d['id']?>"<?=$v('department_id')===(string)$d['id']?' selected':''?>><?=View::escape($d['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="project_id">Related project</label><select id="project_id" name="project_id"><option value="">No project</option><?php foreach($projects as$p):?><option value="<?=(int)$p['id']?>"<?=$v('project_id')===(string)$p['id']?' selected':''?>><?=View::escape($p['title'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="impact_date">Impact date</label><input id="impact_date" name="impact_date" type="date" value="<?=View::escape($v('impact_date'))?>"></div><div class="form-field"><label for="location_text">Location</label><input id="location_text" name="location_text" maxlength="255" value="<?=View::escape($v('location_text'))?>"></div><?php foreach(['summary'=>'Summary','body'=>'Full story','beneficiaries'=>'Beneficiaries']as$f=>$label):?><div class="form-field span-2"><label for="<?=$f?>"><?=$label?></label><textarea id="<?=$f?>" name="<?=$f?>" rows="<?=$f==='body'?10:5?>"><?=View::escape($v($f))?></textarea></div><?php endforeach;?><div class="form-field span-2"><label for="featured_media_id">Existing image</label><select id="featured_media_id" name="featured_media_id"><option value="">No image</option><?php foreach($images as$image):?><option value="<?=(int)$image['id']?>"<?=$v('featured_media_id')===(string)$image['id']?' selected':''?>><?=View::escape($image['original_name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="featured_image">Upload image</label><input id="featured_image" name="featured_image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div><div class="form-field"><label for="featured_alt_text">Image description</label><input id="featured_alt_text" name="featured_alt_text" maxlength="255"></div></div></section><div class="form-actions"><button class="button <?=$canPublish?'button-secondary':'button-primary'?>" name="submit_action" value="save">Save</button><?php if($canPublish):?><button class="button button-primary" name="submit_action" value="publish">Save and publish</button><?php endif;?></div></form>
